import { isNil } from 'lodash-es';
import { Row } from 'react-table';

import { _convertToNumberIfPureNumber } from '../../../core/utils/string-utils.js';
import type { TableColumn } from '../../types/shared-table-types.js';

/**
 * Converts value to bigint if it exceeds MAX_SAFE_INTEGER
 */
function convertToBigInt(value: string | number) {
  const valueAsNumber =
    typeof value === 'number'
      ? value
      : Number.isNaN(+value)
      ? null
      : _convertToNumberIfPureNumber(value);

  return (valueAsNumber as number) > Number.MAX_SAFE_INTEGER
    ? BigInt(value)
    : valueAsNumber;
}

/**
 * Gets the value of a column by its id or accessor from original row data.
 * Using the given columnId gets the corresponding accessor and looks for the value in
 * the original row data. If the column is not found, the columnId is used as a fallback.
 * @param row - The react-table row object containing the original data
 * @param columnId - react-table column id
 * @returns The value of the column
 */
export function getColumnValueByIdOrAccessor(row: Row, columnId: string) {
  const cell = row?.cells?.find(
    (cell) => cell.column && cell.column.id === columnId,
  );
  const column = cell ? (cell.column as TableColumn) : undefined;

  let result: unknown = undefined;
  if (column && typeof column.accessor === 'string') {
    result = column.accessor
      .split('.')
      .reduce((obj, key) => obj[key], row.original);
  }

  if (column && typeof column.accessor === 'function') {
    const data: Record<string, unknown>[] = [];
    result = column.accessor(row.original, row.index, {
      subRows: [],
      data,
      depth: 0,
    });
  }
  // if the column was not found, use values[columnId]
  if (column === undefined) {
    result = row?.values[columnId];
  }
  // if the value is an object, check if it has a cellValue field.
  // this is notebooks/dashboard-specific knowledge and should be replaced
  // later by a more generic solution (e.g. sortAccessor).
  if (result !== null && typeof result === 'object' && 'cellValue' in result) {
    result = result.cellValue;
  }

  return result as string | number | bigint | null | undefined;
}

/**
 * Compares number values in columns.

 */
export function numberlikeCompare(
  rowA: Row,
  rowB: Row,
  columnId: string,
  descending: boolean,
): number {
  let valueA = getColumnValueByIdOrAccessor(rowA, columnId);
  let valueB = getColumnValueByIdOrAccessor(rowB, columnId);

  if (typeof valueA === 'string') {
    valueA = convertToBigInt(valueA);
    if (typeof valueB === 'number') {
      valueB = convertToBigInt(valueB);
    }
  }

  if (typeof valueB === 'string') {
    valueB = convertToBigInt(valueB);
    if (typeof valueA === 'number') {
      valueA = convertToBigInt(valueA);
    }
  }

  return getComparingValue(valueA, valueB, rowA.index, rowB.index, descending);
}

/**
 * Compares string values in columns.
 */
export function stringlikeCompare(
  rowA: Row,
  rowB: Row,
  columnId: string,
  descending: boolean,
): number {
  const valueA = getColumnValueByIdOrAccessor(rowA, columnId);
  const valueB = getColumnValueByIdOrAccessor(rowB, columnId);

  return getComparingValue(valueA, valueB, rowA.index, rowB.index, descending);
}

/**
 * Compares datetime values in columns.
 */
export function datelikeCompare(
  rowA: Row,
  rowB: Row,
  columnId: string,
  descending: boolean,
): number {
  let valueA = rowA.values[columnId]?.cellValue ?? rowA.values[columnId];
  let valueB = rowB.values[columnId]?.cellValue ?? rowB.values[columnId];

  if (valueA instanceof Date) {
    valueA = valueA.getTime();
  }

  if (valueB instanceof Date) {
    valueB = valueB.getTime();
  }

  if (typeof valueA === 'string') {
    valueA = new Date(valueA).getTime();
  }

  if (typeof valueB === 'string') {
    valueB = new Date(valueB).getTime();
  }

  return getComparingValue(valueA, valueB, rowA.index, rowB.index, descending);
}

/**
 * Since v7 of react-table uses an unstable sorting algorithm, the
 * order of rows may still change even though all values in the sorted
 * column are equal - to mitigate this, we have to preserve the original
 * row index of the values being "sorted".
 */
function compareIndices(
  indexA: number,
  indexB: number,
  descending: boolean,
): number {
  return descending ? indexB - indexA : indexA - indexB;
}

/**
 * Determines sorting order for two values.
 *
 * @param valueA - The value to be compared to `valueB`
 * @param valueB - The value `valueA` is compared to
 * @param indexA - The original (unsorted) row index of `valueA`
 * @param indexB - The original (unsorted) row index of `valueB`
 * @param descending - Determines whether the sorting algorithm
 * intends to sort values in descending order - the value of this
 * parameter does not influence value comparison and is only
 * relevant when row indices are used to compensate for the unstable
 * sorting algorithm used by the react-table library is v7
 * @returns - `0` when `valueA` and `valueB` are equal,
 * a value `< 0` when `valueA` is lower than `valueB`
 * and a value `> 0` when `valueA` is greater than `valueB`
 */
export function getComparingValue(
  valueA: string | number | bigint | null | undefined,
  valueB: string | number | bigint | null | undefined,
  indexA: number,
  indexB: number,
  descending: boolean,
): number {
  if (isNil(valueA)) {
    if (isNil(valueB)) {
      return compareIndices(indexA, indexB, descending);
    }

    // `null` and `undefined` should always be at the end of the list, regardless of sorting direction (see APM-363741)
    return descending ? -1 : 1;
  }

  if (isNil(valueB)) {
    // `null` and `undefined` should always be at the end of the list, regardless of sorting direction (see APM-363741)
    return descending ? 1 : -1;
  }

  const comp =
    typeof valueA === 'string'
      ? `${valueA}`.localeCompare(`${valueB}`)
      : typeof valueA === 'bigint'
      ? (valueA as bigint) > (valueB as bigint)
        ? 1
        : (valueA as bigint) < (valueB as bigint)
        ? -1
        : 0
      : (valueA as number) - (valueB as number);

  return comp === 0 ? compareIndices(indexA, indexB, descending) : comp;
}
